-- Deal step 1: config, leaders, pools
-- Generated by scripts/generate/generate.mjs from shared/deal/ (workstream B). Don't edit by hand.

CREATE TABLE IF NOT EXISTS LShufWork_Cfg (Seed INTEGER, Mode TEXT, IsPaired INTEGER, IsFull INTEGER, IsMatched INTEGER, IsWhole INTEGER, IsSplit INTEGER, Active INTEGER, RollBiases INTEGER, Balanced INTEGER, Follows INTEGER, PRedealt INTEGER, OffA INTEGER, OffT INTEGER, OffB INTEGER, MA TEXT, MT TEXT, MB TEXT);
DELETE FROM LShufWork_Cfg;
INSERT INTO LShufWork_Cfg SELECT s, m,
  m = 'LSHUF_MODE_SWAP_LEADERS', m = 'LSHUF_MODE_SWAP_ABILITIES', m = 'LSHUF_MODE_SPLIT_MATCHED',
  m IN ('LSHUF_MODE_SWAP_LEADERS', 'LSHUF_MODE_SWAP_ABILITIES'), m IN ('LSHUF_MODE_SPLIT_MATCHED', 'LSHUF_MODE_SPLIT_RANDOM'),
  m IN ('LSHUF_MODE_SWAP_LEADERS', 'LSHUF_MODE_SWAP_ABILITIES', 'LSHUF_MODE_SPLIT_MATCHED', 'LSHUF_MODE_SPLIT_RANDOM'),
  m IN ('LSHUF_MODE_SWAP_ABILITIES', 'LSHUF_MODE_SPLIT_RANDOM'),
  dl <> 'LSHUF_DEAL_CHANCE', pe NOT IN ('LSHUF_PERSONA_STAYS', 'LSHUF_PERSONA_REDEALT'), pe = 'LSHUF_PERSONA_REDEALT',
  ab = 'LSHUF_OFF', at = 'LSHUF_OFF', bi = 'LSHUF_OFF', ma, mt, mb
FROM (SELECT COALESCE((SELECT MIN(Seed) FROM LShufSeed), 1) AS s, COALESCE((SELECT Value FROM LShufOptions WHERE Name = 'Mode'), 'LSHUF_MODE_NONE') AS m, COALESCE((SELECT Value FROM LShufOptions WHERE Name = 'Dealing'), 'LSHUF_DEAL_BALANCED') AS dl,
  COALESCE((SELECT Value FROM LShufOptions WHERE Name = 'Personality'), 'LSHUF_PERSONA_FOLLOWS') AS pe, COALESCE((SELECT Value FROM LShufOptions WHERE Name = 'Abilities'), 'LSHUF_REDEALT') AS ab, COALESCE((SELECT Value FROM LShufOptions WHERE Name = 'Attributes'), 'LSHUF_REDEALT') AS at, COALESCE((SELECT Value FROM LShufOptions WHERE Name = 'Biases'), 'LSHUF_REDEALT') AS bi,
  COALESCE((SELECT Value FROM LShufOptions WHERE Name = 'ModdedAbilities'), '0') AS ma, COALESCE((SELECT Value FROM LShufOptions WHERE Name = 'ModdedAttributes'), '0') AS mt, COALESCE((SELECT Value FROM LShufOptions WHERE Name = 'ModdedBiases'), '0') AS mb) o;

CREATE TABLE IF NOT EXISTS LShufWork_L (LeaderType TEXT PRIMARY KEY, Ability TEXT, AbilityName TEXT, NAttr INTEGER, NMods INTEGER, Known INTEGER, Modded INTEGER, Kept INTEGER, OutReason TEXT, ModOK INTEGER, LTReq INTEGER, Base TEXT, RA TEXT, RT TEXT, RB TEXT, InA INTEGER, InT INTEGER, InB INTEGER, Changed INTEGER, AbilityFrom TEXT, PersonaFrom TEXT, BiasFrom TEXT);
DELETE FROM LShufWork_L;
INSERT INTO LShufWork_L (LeaderType) SELECT DISTINCT LeaderType FROM Leaders WHERE IsMajorLeader = 1;
UPDATE LShufWork_L SET Ability = (SELECT MIN(lt.TraitType) FROM LeaderTraits lt JOIN Traits t ON t.TraitType = lt.TraitType
  WHERE lt.LeaderType = LShufWork_L.LeaderType AND t.Name IS NOT NULL);
UPDATE LShufWork_L SET
  AbilityName = (SELECT t.Name FROM Traits t WHERE t.TraitType = LShufWork_L.Ability),
  NAttr = (SELECT COUNT(DISTINCT lt.TraitType) FROM LeaderTraits lt
    WHERE lt.LeaderType = LShufWork_L.LeaderType AND lt.TraitType IN (SELECT TraitType FROM LShufAttributeTraits)),
  NMods = (SELECT COUNT(DISTINCT tm.ModifierId) FROM TraitModifiers tm WHERE tm.TraitType = LShufWork_L.Ability),
  Known = EXISTS (SELECT 1 FROM LShufKnownLeaders k WHERE k.LeaderType = LShufWork_L.LeaderType),
  Modded = EXISTS (SELECT 1 FROM LShufKnownLeaders k WHERE k.LeaderType = LShufWork_L.LeaderType AND k.IsModded = 1),
  Kept = EXISTS (SELECT 1 FROM LShufKept k WHERE k.LeaderType = LShufWork_L.LeaderType),
  OutReason = (SELECT MIN(o.Reason) FROM LShufOut o WHERE o.LeaderType = LShufWork_L.LeaderType),
  ModOK = EXISTS (SELECT 1 FROM LShufModOK k WHERE k.LeaderType = LShufWork_L.LeaderType),
  LTReq = EXISTS (SELECT 1 FROM TraitModifiers tm JOIN Modifiers m ON m.ModifierId = tm.ModifierId
    JOIN RequirementSetRequirements rs ON rs.RequirementSetId IN (m.OwnerRequirementSetId, m.SubjectRequirementSetId)
    JOIN Requirements r ON r.RequirementId = rs.RequirementId
    WHERE tm.TraitType = LShufWork_L.Ability AND r.RequirementType = 'REQUIREMENT_PLAYER_LEADER_TYPE_MATCHES');
UPDATE LShufWork_L SET Base = CASE
  WHEN Known = 0 THEN 'unknown' WHEN Kept = 1 THEN 'kept'
  WHEN OutReason IS NOT NULL THEN OutReason WHEN NMods = 0 AND NAttr = 0 THEN 'observer'
  WHEN Modded = 1 AND ModOK = 0 THEN 'modded-notok' WHEN Modded = 1 AND LTReq = 1 THEN 'modded-leadertype'
  ELSE NULL END;
UPDATE LShufWork_L SET
  RA = COALESCE(Base, CASE WHEN Modded = 1 AND (SELECT MA FROM LShufWork_Cfg) <> '1' THEN 'modded-off' END),
  RT = COALESCE(Base, CASE WHEN Modded = 1 AND (SELECT MT FROM LShufWork_Cfg) <> '1' THEN 'modded-off' END),
  RB = COALESCE(Base, CASE WHEN Modded = 1 AND (SELECT MB FROM LShufWork_Cfg) <> '1' THEN 'modded-off' END);

CREATE TABLE IF NOT EXISTS LShufWork_Axis (Axis TEXT PRIMARY KEY, Off INTEGER, NElig INTEGER, Dealt INTEGER, Level TEXT, Fallback INTEGER);
DELETE FROM LShufWork_Axis;
INSERT INTO LShufWork_Axis (Axis, Off, NElig) SELECT 'A', (SELECT OffA FROM LShufWork_Cfg), (SELECT COUNT(*) FROM LShufWork_L WHERE RA IS NULL) UNION ALL SELECT 'T', (SELECT OffT FROM LShufWork_Cfg), (SELECT COUNT(*) FROM LShufWork_L WHERE RT IS NULL)
  UNION ALL SELECT 'B', (SELECT OffB FROM LShufWork_Cfg), (SELECT COUNT(*) FROM LShufWork_L WHERE RB IS NULL);
UPDATE LShufWork_Axis SET
  Dealt = (Off = 0 AND (SELECT Active FROM LShufWork_Cfg) = 1 AND NElig >= 2),
  Fallback = (Off = 0 AND (SELECT Active FROM LShufWork_Cfg) = 1 AND NElig < 2),
  Level = CASE WHEN Off = 1 THEN NULL WHEN (SELECT Active FROM LShufWork_Cfg) = 0 THEN 'mode-none'
    WHEN NElig < 2 THEN 'too-few' ELSE NULL END;

CREATE TABLE IF NOT EXISTS LShufWork_Pool (Axis TEXT, LeaderType TEXT, Rank INTEGER, K INTEGER, Pos INTEGER, N INTEGER, PRIMARY KEY (Axis, LeaderType));
DELETE FROM LShufWork_Pool;
INSERT INTO LShufWork_Pool (Axis, LeaderType) SELECT 'A', LeaderType FROM LShufWork_L WHERE RA IS NULL AND (SELECT Dealt FROM LShufWork_Axis WHERE Axis = 'A') = 1;
INSERT INTO LShufWork_Pool (Axis, LeaderType) SELECT 'T', LeaderType FROM LShufWork_L WHERE RT IS NULL AND (SELECT Dealt FROM LShufWork_Axis WHERE Axis = 'T') = 1;
INSERT INTO LShufWork_Pool (Axis, LeaderType) SELECT 'TS', LeaderType FROM LShufWork_L WHERE RT IS NULL AND (SELECT Dealt FROM LShufWork_Axis WHERE Axis = 'T') = 1;
INSERT INTO LShufWork_Pool (Axis, LeaderType) SELECT 'B', LeaderType FROM LShufWork_L WHERE RB IS NULL AND (SELECT Dealt FROM LShufWork_Axis WHERE Axis = 'B') = 1;
INSERT INTO LShufWork_Pool (Axis, LeaderType) SELECT 'P', LeaderType FROM LShufWork_L WHERE RA IS NULL AND (SELECT PRedealt FROM LShufWork_Cfg) = 1 AND ((SELECT Dealt FROM LShufWork_Axis WHERE Axis = 'A') = 1 OR ((SELECT OffA FROM LShufWork_Cfg) = 1 AND (SELECT Active FROM LShufWork_Cfg) = 1 AND (SELECT NElig FROM LShufWork_Axis WHERE Axis = 'A') >= 2));
UPDATE LShufWork_Pool SET Rank = (SELECT COUNT(*) FROM LShufWork_Pool o WHERE o.Axis = LShufWork_Pool.Axis AND (o.LeaderType < LShufWork_Pool.LeaderType)) WHERE 1 = 1;
UPDATE LShufWork_Pool SET K = ((((((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (CASE Axis WHEN 'TS' THEN 4 WHEN 'P' THEN 10 ELSE 1 END) * 104729 + (Rank) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (CASE Axis WHEN 'TS' THEN 4 WHEN 'P' THEN 10 ELSE 1 END) * 104729 + (Rank) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859) * (((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (CASE Axis WHEN 'TS' THEN 4 WHEN 'P' THEN 10 ELSE 1 END) * 104729 + (Rank) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (CASE Axis WHEN 'TS' THEN 4 WHEN 'P' THEN 10 ELSE 1 END) * 104729 + (Rank) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859)) + 1664525) % 67108859), N = (SELECT COUNT(*) FROM LShufWork_Pool o WHERE o.Axis = LShufWork_Pool.Axis);
UPDATE LShufWork_Pool SET Pos = (SELECT COUNT(*) FROM LShufWork_Pool o WHERE o.Axis = LShufWork_Pool.Axis AND (o.K < LShufWork_Pool.K OR (o.K = LShufWork_Pool.K AND (o.LeaderType < LShufWork_Pool.LeaderType)))) WHERE 1 = 1;
CREATE TABLE IF NOT EXISTS LShufWork_Donor (Axis TEXT, LeaderType TEXT, Donor TEXT, PRIMARY KEY (Axis, LeaderType));
DELETE FROM LShufWork_Donor;
INSERT INTO LShufWork_Donor (Axis, LeaderType, Donor) SELECT p.Axis, p.LeaderType, d.LeaderType
  FROM LShufWork_Pool p JOIN LShufWork_Pool d ON d.Axis = p.Axis AND d.Pos = (p.Pos + 1) % p.N;
